export class FileManifestCache extends BaseCache {
	private manifestKey(filename: string): string {
		return `files:cache:${filename}`;
	}

	async setEntry(filename: string, entry: FileManifestEntry): Promise<void> {
		const sanitized: Record<string, unknown> = {};
		for (const [k, v] of Object.entries(entry)) {
			if (v !== undefined && v !== null) sanitized[k] = v;
		}
		await this.hset(this.manifestKey(filename), sanitized);
	}

	async getEntry(filename: string): Promise<FileManifestEntry | null> {
		return this.hgetall<FileManifestEntry>(this.manifestKey(filename));
	}

	async deleteEntry(filename: string): Promise<void> {
		await this.del(this.manifestKey(filename));
	}

	async hasEntry(filename: string): Promise<boolean> {
		return this.exists(this.manifestKey(filename));
	}

	async listAll(): Promise<Array<{ filename: string; entry: FileManifestEntry }>> {
		const keys = await this.scan("files:cache:*");
		const out: Array<{ filename: string; entry: FileManifestEntry }> = [];
		for (const k of keys) {
			const entry = await this.hgetall<FileManifestEntry>(k);
			if (entry) out.push({ filename: k.slice("files:cache:".length), entry });
		}
		return out;
	}

	async listBySource(source: FileSource): Promise<string[]> {
		const all = await this.listAll();
		return all.filter((x) => x.entry.source === source).map((x) => x.filename);
	}

	async count(): Promise<{ deezer: number; chipbot: number; total: number }> {
		const all = await this.listAll();
		let deezer = 0;
		let chipbot = 0;
		for (const { entry } of all) {
			if (entry.source === "deezer") deezer++;
			else if (entry.source === "chipbot") chipbot++;
		}
		return { deezer, chipbot, total: all.length };
	}
}
```

