async fn get_track_file_by_isrc_inner(
    state: &AppState,
    raw_isrc: String,
    raw_format: String,
    headers: &HeaderMap,
    bw: Option<&BandwidthOp>,
) -> Result<Response, String> {
    let FileRequestValidation {
        isrc,
        requested_format,
        errors,
    } = validate_file_request(&raw_isrc, &raw_format);
    tracing::debug!(
        target: "CHIPBOT",
        isrc = ?isrc,
        raw_isrc,
        raw_format,
        requested_format,
        range = ?headers.get(header::RANGE),
        "getTrackFileByIsrc controller input"
    );
    if errors.has_errors {
        return Ok(errors.into_response());
    }
    let isrc = isrc.expect("validated ISRC");

    if let Some(response) = send_cached_chipbot_track(state, headers, &isrc, bw).await? {
        return Ok(response);
    }

    let track = state.chipbot.get_track_by_isrc(&isrc, bw).await;
    tracing::debug!(
        target: "CHIPBOT",
        isrc,
        found = track.is_some(),
        has_audio = track
            .as_ref()
            .and_then(|track| track.audio.as_ref())
            .is_some_and(|audio| !audio.url.is_empty()),
        "getTrackFileByIsrc chipbot lookup result"
    );
    if let Some(track) = track {
        if let Some(file_path) = cache_chipbot_track(state, &track, &isrc, bw).await? {
            tracing::info!(
                target: "CHIPBOT",
                isrc,
                origin = "chipbot",
                "audio source: CHIPBOT API (downloaded + cached)"
            );
            if let Some(op) = bw {
                op.set_provider(BandwidthProvider::Chipbot);
                op.mark_cache(CacheMark::Miss);
            }
            // Fire-and-forget: the handle is a spawned task, deliberately detached.
            drop(
                state
                    .api_db
                    .fire_and_forget_track_counter(TrackCounterSource::Chipbot),
            );
            let extension = file_path
                .extension()
                .and_then(|extension| extension.to_str())
                .map(|extension| format!(".{extension}"))
                .unwrap_or_else(|| ".mp3".to_string());
            return audio_file_response(&file_path, &extension, headers).await;
        }
    }

    Ok(not_found_response(format!(
        "Track file not found on Chipbot [isrc: {isrc}]"
    )))
}
