113	/// `Number.parseInt(s, 10)`: optional sign + leading decimal digits, `None`
114	/// when no digits lead the (trimmed) input.
115	fn parse_int_prefix(raw: &str) -> Option<i64> {
116	    let s = raw.trim_start();
117	    let (negative, rest) = match s.as_bytes().first() {
118	        Some(b'-') => (true, &s[1..]),
119	        Some(b'+') => (false, &s[1..]),
120	        _ => (false, s),
121	    };
122	    let digits = rest
123	        .as_bytes()
124	        .iter()
125	        .take_while(|b| b.is_ascii_digit())
126	        .count();
127	    if digits == 0 {
128	        return None;
129	    }
130	    let magnitude =
131	        rest[..digits]
132	            .parse::<i64>()
133	            .unwrap_or(if negative { i64::MIN } else { i64::MAX });
134	    Some(if negative { -magnitude } else { magnitude })
135	}
