//! Resultados del núcleo — SIN tipos de frontend.
//!
//! El núcleo nunca importa `axum`: devuelve datos (el envelope común
//! `ResultEnvelope`, que es puro serde y parte del contrato wire con
//! api-music) o una referencia a un archivo de audio en disco. Cada frontend
//! traduce esto a su protocolo (el HTTP aplica Range/RFC 7233 y status codes).

use std::path::PathBuf;

use serde_json::Value;

use crate::error::ResultEnvelope;

/// Resultado de servir audio desde el pipeline de archivos (Deezer/Chipbot).
#[derive(Debug)]
pub enum AudioServe {
    /// Archivo listo en disco; el frontend hace el streaming (Range incluido).
    File {
        path: PathBuf,
        content_type: &'static str,
    },
    /// Fallo con el envelope común ya status-codeado (validación, 404 de
    /// caché, 503 de contención de lock, errores upstream...).
    Fail(ResultEnvelope<()>),
}

/// Resultado del dispatcher genérico `MusicSystem::resolve`.
#[derive(Debug)]
pub enum MusicOutcome {
    /// Respuesta JSON con el envelope común (statusCode ya fijado dentro).
    Datos(Box<ResultEnvelope<Value>>),
    /// Audio en disco; el frontend decide cómo transportar los bytes.
    Audio {
        path: PathBuf,
        content_type: &'static str,
    },
}

impl From<AudioServe> for MusicOutcome {
    fn from(serve: AudioServe) -> Self {
        match serve {
            AudioServe::File { path, content_type } => MusicOutcome::Audio { path, content_type },
            AudioServe::Fail(envelope) => MusicOutcome::Datos(Box::new(envelope.into_value())),
        }
    }
}

