1	//! Orquestación de archivos Deezer — movida desde `http/controllers/deezer.rs`
2	//! (Fase 2 del plan). Lógica idéntica; lo único que cambia es la frontera:
3	//! aquí no hay tipos de axum. El frontend HTTP aplica Range/streaming sobre
4	//! el `AudioServe::File` devuelto.
5	//!
6	//! Contrato observable (espejo exacto del TS, ver docs/CASOS_DE_USO.md):
7	//! - archivo (formato explícito): lock de descarga acotado (3 intentos,
8	//!   esperas de 60 s, 503 en contención), short-circuit de fs-cache en cada
9	//!   acquire/despertar, heartbeat de extensión del lock cada 15 s durante la
10	//!   descarga, gate mp3val, manifiesto, contador `deezer` y archivo listo.
11	//! - archivo (formato omitido): resuelve el mejor formato que el track
12	//!   expone (`FILESIZE_*` > 0, FLAC → MP3 → AAC) y corre el mismo pipeline;
13	//!   404 sin formato; retry sin FLAC ante 403 `format_rights`.
14	//! - solo-caché: probe de fs, nunca descarga; marca cache-hit de bandwidth
15	//!   incluso en miss (paridad TS — gap 1 del catálogo, se corrige en Fase 3).
16	//! - tokens: tokens de sesión + token de track cacheado (TTL dinámico de
17	//!   Deezer), 401 en errores de licencia, 500 en fallos de transporte.
18	
19	use std::path::Path as FsPath;
20	use std::sync::Arc;
21	use std::time::Duration;
22	
23	use serde::Serialize;
24	use serde_json::Value;
25	
26	use crate::audio::{
27	    calculate_key, download_deezer_track, fix_file, validate_directory, validate_file,
28	    DownloadError, DownloadParams, TrackId3Metadata,
29	};
30	use crate::cache::keys::deezer_track_token_key;
31	use crate::cache::locks::{DownloadLock, DownloadLockGuard};
32	use crate::cache::manifest::{self, FileManifestEntry};
33	use crate::clients::TrackCounterSource;
34	use crate::error::{ApiError, ErrorContext, ErrorType, ResultEnvelope};
35	use crate::providers::deezer::{deezer_image_url, token_related_ttl, DeezerArlFailureContext};
36	use crate::telemetry::{BandwidthOp, BandwidthProvider, CacheMark};
37	
38	use super::result::AudioServe;
39	use super::MusicSystem;
40	
41	/// Bounded lock retry (deezer-controller.ts:359-361): cap so a poisoned lock
42	/// degrades to 503 instead of holding the socket open forever.
43	const MAX_LOCK_ATTEMPTS: u32 = 3;
44	const LOCK_WAIT_MS: u64 = 60_000;
45	/// `setInterval(extend, 15_000)` heartbeat while a download holds the lock.
46	const LOCK_EXTEND_INTERVAL: Duration = Duration::from_millis(15_000);
47	/// Thumbnail fetch budget in `buildDeezerId3Metadata` (5 s AbortController).
48	const THUMBNAIL_TIMEOUT: Duration = Duration::from_secs(5);
49	const DOWNLOAD_OVERALL_TIMEOUT_MS: u64 = 60_000;
50	const DOWNLOAD_CHUNK_TIMEOUT_MS: u64 = 10_000;
51	
52	// ---------------------------------------------------------------------------
53	// Format registry (`shared/lib/deezer-formats.ts` + shared alias table)
54	// ---------------------------------------------------------------------------
55	
56	/// `DeezerFormatSpec`: everything the download pipeline needs per container.
57	pub struct DeezerFormatSpec {
58	    /// Canonical token used for cache/lock keys and logs.
59	    pub token: &'static str,
60	    /// On-disk extension (with leading dot) — also the file-cache suffix.
61	    pub extension: &'static str,
62	    /// HTTP Content-Type served to the client / Lavalink.
63	    pub content_type: &'static str,
64	    /// Container family for validation + tagging (`mp3` | `flac` | `mp4`).
65	    pub container: &'static str,
66	    /// Deezer `get_url` format priority list.
67	    pub deezer_formats: &'static [&'static str],
68	}
69	
70	pub static MP3: DeezerFormatSpec = DeezerFormatSpec {
71	    token: "mp3",
72	    extension: ".mp3",
73	    content_type: "audio/mpeg",
74	    container: "mp3",
75	    deezer_formats: &["MP3_320", "MP3_256", "MP3_128", "MP3_64"],
76	};
77	
78	pub static FLAC: DeezerFormatSpec = DeezerFormatSpec {
79	    token: "flac",
80	    extension: ".flac",
81	    content_type: "audio/flac",
82	    container: "flac",
83	    deezer_formats: &["FLAC"],
84	};
85	
86	pub static AAC: DeezerFormatSpec = DeezerFormatSpec {
87	    token: "aac",
88	    extension: ".m4a",
89	    content_type: "audio/mp4",
90	    container: "mp4",
91	    deezer_formats: &["AAC_64"],
92	};
93	
94	/// `resolveDeezerFormat(raw)` — alias → spec, `None` when unsupported
95	/// (callers return 400). Accepts leading dots and any case.
96	pub fn resolve_deezer_format(raw: &str) -> Option<&'static DeezerFormatSpec> {
97	    let key = raw.trim().to_lowercase();
98	    let key = key.trim_start_matches('.');
99	    match key {
100	        "mp3" | "mp3_320" | "mp3_256" | "mp3_128" | "mp3_64" => Some(&MP3),
101	        "flac" => Some(&FLAC),
102	        "aac" | "aac_64" | "m4a" | "mp4" => Some(&AAC),
103	        _ => None,
104	    }
105	}
106	
107	/// Availability probe order for requests that omit `{format}`: highest
108	/// quality first. Deezer reports `FILESIZE_* = 0` (or omits the field) when
109	/// the track cannot be served in that format for the active ARL.
110	static DEFAULT_FORMAT_PRIORITY: [(&str, &DeezerFormatSpec); 6] = [
111	    ("FILESIZE_FLAC", &FLAC),
112	    ("FILESIZE_MP3_320", &MP3),
113	    ("FILESIZE_MP3_256", &MP3),
114	    ("FILESIZE_MP3_128", &MP3),
115	    ("FILESIZE_MP3_64", &MP3),
116	    ("FILESIZE_AAC_64", &AAC),
117	];
118	
119	/// Pick the best available spec from the track's song data (`FILESIZE_*`
120	/// fields). `None` when the track exposes no downloadable format.
121	pub fn resolve_default_deezer_format(results: &Value) -> Option<&'static DeezerFormatSpec> {
122	    resolve_from_priority(results, &DEFAULT_FORMAT_PRIORITY)
123	}
124	
125	/// Same resolution but skipping FLAC — the 403-downgrade retry: cached
126	/// `FILESIZE_*` can promise FLAC that the *current* ARL can no longer serve
127	/// (tier rotation), and a propagated 403 would dead-stamp the track for 72 h
128	/// upstream even though MP3 works.
129	pub fn resolve_default_deezer_format_no_flac(results: &Value) -> Option<&'static DeezerFormatSpec> {
130	    resolve_from_priority(results, &DEFAULT_FORMAT_PRIORITY[1..])
131	}
132	
133	fn resolve_from_priority(
134	    results: &Value,
135	    priority: &[(&str, &'static DeezerFormatSpec)],
136	) -> Option<&'static DeezerFormatSpec> {
137	    priority
138	        .iter()
139	        .find(|(key, _)| filesize_field(results, key) > 0)
140	        .map(|(_, spec)| *spec)
141	}
142	
143	/// Deezer serialises `FILESIZE_*` as strings (`"0"` = unavailable), but some
144	/// payloads carry plain numbers — accept both, anything else counts as 0.
145	fn filesize_field(results: &Value, key: &str) -> u64 {
146	    match results.get(key) {
147	        Some(Value::String(raw)) => raw.trim().parse().unwrap_or(0),
148	        Some(value) => value.as_u64().unwrap_or(0),
149	        None => 0,
150	    }
151	}
152	
153	/// The deezer format names in `DEFAULT_FORMAT_PRIORITY`, order preserved
154	/// (bitrate duplicates kept — Deezer echoes back whichever one it grants).
155	fn combined_deezer_formats() -> Vec<&'static str> {
156	    DEFAULT_FORMAT_PRIORITY
157	        .iter()
158	        .map(|(key, _)| key.strip_prefix("FILESIZE_").unwrap_or(key))
159	        .collect()
160	}
161	
162	/// Map the deezer format names Deezer actually granted back to canonical
163	/// tokens, in `DEFAULT_FORMAT_PRIORITY` order and deduped (every `MP3_*`
164	/// bitrate collapses to a single `mp3`).
165	fn granted_formats_to_tokens(granted: &[String]) -> Vec<&'static str> {
166	    let mut tokens: Vec<&'static str> = Vec::new();
167	    for (key, spec) in DEFAULT_FORMAT_PRIORITY.iter() {
168	        let name = key.strip_prefix("FILESIZE_").unwrap_or(key);
169	        if granted.iter().any(|g| g.eq_ignore_ascii_case(name)) && !tokens.contains(&spec.token) {
170	            tokens.push(spec.token);
171	        }
172	    }
173	    tokens
174	}
175	
176	/// Guard numérico del track ID (compartido por todos los flujos de archivo).
177	pub fn is_numeric_track_id(v: &str) -> bool {
178	    !v.is_empty() && v.bytes().all(|b| b.is_ascii_digit())
179	}
180	
181	// ---------------------------------------------------------------------------
182	// Payloads (wire shapes — serde puro, parte del contrato con api-music)
183	// ---------------------------------------------------------------------------
184	
185	/// `getTrackTokensHandler` response body (session + track tokens, no bytes).
186	#[derive(Debug, Serialize)]
187	pub struct TrackRawData {
188	    pub track_id: String,
189	    pub track_format: String,
190	    pub session_id: String,
191	    pub api_token: String,
192	    pub license_token: String,
193	    pub track_token: String,
194	    pub track_url: String,
195	}
196	
197	/// `GET /deezer/tracks/{track_id}/available-formats` response payload.
198	#[derive(Debug, Serialize)]
199	pub struct AvailableFormatsData {
200	    pub formats: Vec<&'static str>,
201	}
202	
203	// ---------------------------------------------------------------------------
204	// Helpers de envelope (idénticos a los del controlador original)
205	// ---------------------------------------------------------------------------
206	
207	fn validation_error(message: &'static str) -> ApiError {
208	    ApiError::new(message, ErrorType::Validation, ErrorContext::Api).with_status(400)
209	}
210	
211	fn internal_error() -> ApiError {
212	    ApiError::new(
213	        "Internal server error",
214	        ErrorType::Internal,
215	        ErrorContext::Api,
216	    )
217	    .with_status(500)
218	}
219	
220	fn internal_500<T: Serialize>() -> ResultEnvelope<T> {
221	    let mut result = ResultEnvelope::<T>::new();
222	    result.add_error(&internal_error());
223	    result
224	}
225	
226	fn fail_with(errors: &[ApiError]) -> ResultEnvelope<()> {
227	    let mut result = ResultEnvelope::<()>::new();
228	    for error in errors {
229	        result.add_error(error);
230	    }
231	    result
232	}
233	
234	// ---------------------------------------------------------------------------
235	// ID3 metadata (`shared/lib/deezer-utils.ts` buildDeezerId3Metadata)
236	// ---------------------------------------------------------------------------
237	
238	/// Build the ID3 payload for the download pipeline. Cover art is fetched
239	/// here (5 s budget); any network failure just drops the image — it never
240	/// blocks the cache write.
241	async fn build_deezer_id3_metadata(
242	    http: &reqwest::Client,
243	    track: &Value,
244	    track_id: &str,
245	    default_image: &str,
246	) -> TrackId3Metadata {
247	    let s = |key: &str| track.get(key).and_then(Value::as_str).unwrap_or("");
248	
249	    let song_title = match s("SNG_TITLE") {
250	        "" => "Unknown Title",
251	        title => title,
252	    };
253	    let uploader_name = match s("ART_NAME") {
254	        "" => "Unknown Artist",
255	        name => name,
256	    };
257	    let artist = match track.get("ARTISTS").and_then(Value::as_array) {
258	        Some(artists) if !artists.is_empty() => artists
259	            .iter()
260	            .map(|a| a.get("ART_NAME").and_then(Value::as_str).unwrap_or(""))
261	            .collect::<Vec<_>>()
262	            .join(", "),
263	        _ => uploader_name.to_string(),
264	    };
265	
266	    let thumbnail_url = match s("ALB_PICTURE") {
267	        "" => default_image.to_string(),
268	        picture => deezer_image_url(picture, "250x250"),
269	    };
270	
271	    let mut image_jpeg = None;
272	    if !thumbnail_url.is_empty() {
273	        let fetch = async {
274	            let response = http.get(&thumbnail_url).send().await?;
275	            if response.status().is_success() {
276	                response.bytes().await.map(Some)
277	            } else {
278	                Ok(None)
279	            }
280	        };
281	        match tokio::time::timeout(THUMBNAIL_TIMEOUT, fetch).await {
282	            Ok(Ok(Some(bytes))) => image_jpeg = Some(bytes.to_vec()),
283	            Ok(Ok(None)) => {}
284	            Ok(Err(error)) => {
285	                let error: reqwest::Error = error;
286	                tracing::warn!(target: "DEEZER", error = %error, "Failed to download thumbnail");
287	            }
288	            Err(_) => {
289	                tracing::warn!(target: "DEEZER", "Failed to download thumbnail: timeout");
290	            }
291	        }
292	    }
293	
294	    let year = track
295	        .get("PHYSICAL_RELEASE_DATE")
296	        .and_then(Value::as_str)
297	        .and_then(|date| date.get(..4))
298	        .and_then(|y| y.parse::<i32>().ok());
299	
300	    let duration_ms = track
301	        .get("DURATION")
302	        .and_then(Value::as_str)
303	        .and_then(|seconds| seconds.parse::<u32>().ok())
304	        .map(|seconds| seconds * 1000);
305	
306	    TrackId3Metadata {
307	        title: Some(song_title.to_string()),
308	        artist: Some(artist),
309	        album: Some(match s("ALB_TITLE") {
310	            "" => uploader_name.to_string(),
311	            album => album.to_string(),
312	        }),
313	        year,
314	        duration_ms,
315	        source: Some("deezer".to_string()),
316	        track_id: Some(track_id.to_string()),
317	        isrc: track.get("ISRC").and_then(Value::as_str).map(str::to_owned),
318	        comment: Some(thumbnail_url),
319	        image_jpeg,
320	    }
321	}
322	
323	/// Release a held download lock, logging (never propagating) failures.
324	async fn release_lock(guard: DownloadLockGuard, track_id: &str) {
325	    if let Err(error) = guard.release().await {
326	        tracing::warn!(
327	            target: "DEEZER",
328	            track_id,
329	            error = %error,
330	            "Failed to release download lock"
331	        );
332	    }
333	}
334	
335	// ---------------------------------------------------------------------------
336	// Casos 3-9 — tokens, formatos y archivos (impl del orquestador)
337	// ---------------------------------------------------------------------------
338	
339	impl MusicSystem {
340	    /// Caso 3 — tokens de sesión/track (`getTrackTokensHandler`).
341	    pub async fn cancion_tokens(
342	        &self,
343	        track_id: &str,
344	        bw: Option<&BandwidthOp>,
345	    ) -> ResultEnvelope<TrackRawData> {
346	        let mut result = ResultEnvelope::<TrackRawData>::new();
347	        tracing::debug!(target: "DEEZER", track_id, "getTrackTokens controller input");
348	
349	        let context = DeezerArlFailureContext {
350	            track_id: Some(track_id.to_string()),
351	            ..Default::default()
352	        };
353	        let Some(tokens) = self
354	            .deezer
355	            .fetch_session_tokens(false, Some(&context), bw)
356	            .await
357	        else {
358	            result.add_error(
359	                &ApiError::new(
360	                    "Invalid license token in session",
361	                    ErrorType::Internal,
362	                    ErrorContext::Api,
363	                )
364	                .with_status(401),
365	            );
366	            return result;
367	        };
368	
369	        let token_key = deezer_track_token_key(track_id);
370	        let cached_token = match self.redis.get_value(&token_key).await {
371	            Ok(value) => value.and_then(|v| v.as_str().map(str::to_owned)),
372	            Err(error) => {
373	                tracing::error!(target: "DEEZER", error = %error, "DeezerController - getTrack");
374	                return internal_500();
375	            }
376	        };
377	        tracing::debug!(
378	            target: "DEEZER",
379	            track_id,
380	            cache_hit = cached_token.is_some(),
381	            "getTrackTokens track token cache"
382	        );
383	
384	        let track_token = match cached_token {
385	            Some(token) => token,
386	            None => {
387	                let song = match self
388	                    .deezer
389	                    .get_song_data(
390	                        &tokens.session_id,
391	                        &tokens.api_token,
392	                        track_id,
393	                        Some(&context),
394	                        bw,
395	                    )
396	                    .await
397	                {
398	                    Ok(song) => song,
399	                    Err(error) => {
400	                        tracing::error!(target: "DEEZER", error = %error, "DeezerController - getTrack");
401	                        return internal_500();
402	                    }
403	                };
404	                if song.is_error_license_token {
405	                    tracing::error!(
406	                        target: "DEEZER",
407	                        track_id,
408	                        "DeezerController - getTrack - Invalid license token in song data"
409	                    );
410	                    result.add_error(
411	                        &ApiError::new(
412	                            "Invalid license token in song data",
413	                            ErrorType::Internal,
414	                            ErrorContext::Api,
415	                        )
416	                        .with_status(401),
417	                    );
418	                    return result;
419	                }
420	
421	                let results = song.results.unwrap_or(Value::Null);
422	                let token = results
423	                    .get("TRACK_TOKEN")
424	                    .and_then(Value::as_str)
425	                    .unwrap_or("")
426	                    .to_string();
427	                let track_exp = results.get("TRACK_TOKEN_EXPIRE").and_then(Value::as_i64);
428	                let ttl = token_related_ttl(track_exp);
429	                if let Err(error) = self
430	                    .redis
431	                    .set_value(&token_key, &Value::String(token.clone()), Some(ttl))
432	                    .await
433	                {
434	                    tracing::error!(target: "DEEZER", error = %error, "DeezerController - getTrack");
435	                    return internal_500();
436	                }
437	                token
438	            }
439	        };
440	
441	        let data = TrackRawData {
442	            track_id: track_id.to_string(),
443	            track_format: String::new(),
444	            session_id: tokens.session_id,
445	            api_token: tokens.api_token,
446	            license_token: tokens.license_token,
447	            track_token,
448	            track_url: String::new(),
449	        };
450	        tracing::debug!(
451	            target: "DEEZER",
452	            track_id,
453	            has_track_token = !data.track_token.is_empty(),
454	            "getTrackTokens controller response"
455	        );
456	        result.add_data(data);
457	        result
458	    }
