//! Orquestación de archivos Deezer — movida desde `http/controllers/deezer.rs`
//! (Fase 2 del plan). Lógica idéntica; lo único que cambia es la frontera:
//! aquí no hay tipos de axum. El frontend HTTP aplica Range/streaming sobre
//! el `AudioServe::File` devuelto.
//!
//! Contrato observable (espejo exacto del TS, ver docs/CASOS_DE_USO.md):
//! - archivo (formato explícito): lock de descarga acotado (3 intentos,
//!   esperas de 60 s, 503 en contención), short-circuit de fs-cache en cada
//!   acquire/despertar, heartbeat de extensión del lock cada 15 s durante la
//!   descarga, gate mp3val, manifiesto, contador `deezer` y archivo listo.
//! - archivo (formato omitido): resuelve el mejor formato que el track
//!   expone (`FILESIZE_*` > 0, FLAC → MP3 → AAC) y corre el mismo pipeline;
//!   404 sin formato; retry sin FLAC ante 403 `format_rights`.
//! - solo-caché: probe de fs, nunca descarga; marca cache-hit de bandwidth
//!   incluso en miss (paridad TS — gap 1 del catálogo, se corrige en Fase 3).
//! - tokens: tokens de sesión + token de track cacheado (TTL dinámico de
//!   Deezer), 401 en errores de licencia, 500 en fallos de transporte.

use std::path::Path as FsPath;
use std::sync::Arc;
use std::time::Duration;

use serde::Serialize;
use serde_json::Value;

use crate::audio::{
    calculate_key, download_deezer_track, fix_file, validate_directory, validate_file,
    DownloadError, DownloadParams, TrackId3Metadata,
};
use crate::cache::keys::deezer_track_token_key;
use crate::cache::locks::{DownloadLock, DownloadLockGuard};
use crate::cache::manifest::{self, FileManifestEntry};
use crate::clients::TrackCounterSource;
use crate::error::{ApiError, ErrorContext, ErrorType, ResultEnvelope};
use crate::providers::deezer::{deezer_image_url, token_related_ttl, DeezerArlFailureContext};
use crate::telemetry::{BandwidthOp, BandwidthProvider, CacheMark};

use super::result::AudioServe;
use super::MusicSystem;

/// Bounded lock retry (deezer-controller.ts:359-361): cap so a poisoned lock
/// degrades to 503 instead of holding the socket open forever.
const MAX_LOCK_ATTEMPTS: u32 = 3;
const LOCK_WAIT_MS: u64 = 60_000;
/// `setInterval(extend, 15_000)` heartbeat while a download holds the lock.
const LOCK_EXTEND_INTERVAL: Duration = Duration::from_millis(15_000);
/// Thumbnail fetch budget in `buildDeezerId3Metadata` (5 s AbortController).
const THUMBNAIL_TIMEOUT: Duration = Duration::from_secs(5);
const DOWNLOAD_OVERALL_TIMEOUT_MS: u64 = 60_000;
const DOWNLOAD_CHUNK_TIMEOUT_MS: u64 = 10_000;

// ---------------------------------------------------------------------------
// Format registry (`shared/lib/deezer-formats.ts` + shared alias table)
// ---------------------------------------------------------------------------

/// `DeezerFormatSpec`: everything the download pipeline needs per container.
pub struct DeezerFormatSpec {
    /// Canonical token used for cache/lock keys and logs.
    pub token: &'static str,
    /// On-disk extension (with leading dot) — also the file-cache suffix.
    pub extension: &'static str,
    /// HTTP Content-Type served to the client / Lavalink.
    pub content_type: &'static str,
    /// Container family for validation + tagging (`mp3` | `flac` | `mp4`).
    pub container: &'static str,
    /// Deezer `get_url` format priority list.
    pub deezer_formats: &'static [&'static str],
}

pub static MP3: DeezerFormatSpec = DeezerFormatSpec {
    token: "mp3",
    extension: ".mp3",
    content_type: "audio/mpeg",
    container: "mp3",
    deezer_formats: &["MP3_320", "MP3_256", "MP3_128", "MP3_64"],
};

pub static FLAC: DeezerFormatSpec = DeezerFormatSpec {
    token: "flac",
    extension: ".flac",
    content_type: "audio/flac",
    container: "flac",
    deezer_formats: &["FLAC"],
};

pub static AAC: DeezerFormatSpec = DeezerFormatSpec {
    token: "aac",
    extension: ".m4a",
    content_type: "audio/mp4",
    container: "mp4",
    deezer_formats: &["AAC_64"],
};

/// `resolveDeezerFormat(raw)` — alias → spec, `None` when unsupported
/// (callers return 400). Accepts leading dots and any case.
pub fn resolve_deezer_format(raw: &str) -> Option<&'static DeezerFormatSpec> {
    let key = raw.trim().to_lowercase();
    let key = key.trim_start_matches('.');
    match key {
        "mp3" | "mp3_320" | "mp3_256" | "mp3_128" | "mp3_64" => Some(&MP3),
        "flac" => Some(&FLAC),
        "aac" | "aac_64" | "m4a" | "mp4" => Some(&AAC),
        _ => None,
    }
}

/// Availability probe order for requests that omit `{format}`: highest
/// quality first. Deezer reports `FILESIZE_* = 0` (or omits the field) when
/// the track cannot be served in that format for the active ARL.
static DEFAULT_FORMAT_PRIORITY: [(&str, &DeezerFormatSpec); 6] = [
    ("FILESIZE_FLAC", &FLAC),
    ("FILESIZE_MP3_320", &MP3),
    ("FILESIZE_MP3_256", &MP3),
    ("FILESIZE_MP3_128", &MP3),
    ("FILESIZE_MP3_64", &MP3),
    ("FILESIZE_AAC_64", &AAC),
];

/// Pick the best available spec from the track's song data (`FILESIZE_*`
/// fields). `None` when the track exposes no downloadable format.
pub fn resolve_default_deezer_format(results: &Value) -> Option<&'static DeezerFormatSpec> {
    resolve_from_priority(results, &DEFAULT_FORMAT_PRIORITY)
}

/// Same resolution but skipping FLAC — the 403-downgrade retry: cached
/// `FILESIZE_*` can promise FLAC that the *current* ARL can no longer serve
/// (tier rotation), and a propagated 403 would dead-stamp the track for 72 h
/// upstream even though MP3 works.
pub fn resolve_default_deezer_format_no_flac(results: &Value) -> Option<&'static DeezerFormatSpec> {
    resolve_from_priority(results, &DEFAULT_FORMAT_PRIORITY[1..])
}

fn resolve_from_priority(
    results: &Value,
    priority: &[(&str, &'static DeezerFormatSpec)],
) -> Option<&'static DeezerFormatSpec> {
    priority
        .iter()
        .find(|(key, _)| filesize_field(results, key) > 0)
        .map(|(_, spec)| *spec)
}

/// Deezer serialises `FILESIZE_*` as strings (`"0"` = unavailable), but some
/// payloads carry plain numbers — accept both, anything else counts as 0.
fn filesize_field(results: &Value, key: &str) -> u64 {
    match results.get(key) {
        Some(Value::String(raw)) => raw.trim().parse().unwrap_or(0),
        Some(value) => value.as_u64().unwrap_or(0),
        None => 0,
    }
}

/// The deezer format names in `DEFAULT_FORMAT_PRIORITY`, order preserved
/// (bitrate duplicates kept — Deezer echoes back whichever one it grants).
fn combined_deezer_formats() -> Vec<&'static str> {
    DEFAULT_FORMAT_PRIORITY
        .iter()
        .map(|(key, _)| key.strip_prefix("FILESIZE_").unwrap_or(key))
        .collect()
}

/// Map the deezer format names Deezer actually granted back to canonical
/// tokens, in `DEFAULT_FORMAT_PRIORITY` order and deduped (every `MP3_*`
/// bitrate collapses to a single `mp3`).
fn granted_formats_to_tokens(granted: &[String]) -> Vec<&'static str> {
    let mut tokens: Vec<&'static str> = Vec::new();
    for (key, spec) in DEFAULT_FORMAT_PRIORITY.iter() {
        let name = key.strip_prefix("FILESIZE_").unwrap_or(key);
        if granted.iter().any(|g| g.eq_ignore_ascii_case(name)) && !tokens.contains(&spec.token) {
            tokens.push(spec.token);
        }
    }
    tokens
}

/// Guard numérico del track ID (compartido por todos los flujos de archivo).
pub fn is_numeric_track_id(v: &str) -> bool {
    !v.is_empty() && v.bytes().all(|b| b.is_ascii_digit())
}

// ---------------------------------------------------------------------------
// Payloads (wire shapes — serde puro, parte del contrato con api-music)
// ---------------------------------------------------------------------------

/// `getTrackTokensHandler` response body (session + track tokens, no bytes).
#[derive(Debug, Serialize)]
pub struct TrackRawData {
    pub track_id: String,
    pub track_format: String,
    pub session_id: String,
    pub api_token: String,
    pub license_token: String,
    pub track_token: String,
    pub track_url: String,
}

/// `GET /deezer/tracks/{track_id}/available-formats` response payload.
#[derive(Debug, Serialize)]
pub struct AvailableFormatsData {
    pub formats: Vec<&'static str>,
}

// ---------------------------------------------------------------------------
// Helpers de envelope (idénticos a los del controlador original)
// ---------------------------------------------------------------------------

fn validation_error(message: &'static str) -> ApiError {
    ApiError::new(message, ErrorType::Validation, ErrorContext::Api).with_status(400)
}

fn internal_error() -> ApiError {
    ApiError::new(
        "Internal server error",
        ErrorType::Internal,
        ErrorContext::Api,
    )
    .with_status(500)
}

fn internal_500<T: Serialize>() -> ResultEnvelope<T> {
    let mut result = ResultEnvelope::<T>::new();
    result.add_error(&internal_error());
    result
}

fn fail_with(errors: &[ApiError]) -> ResultEnvelope<()> {
    let mut result = ResultEnvelope::<()>::new();
    for error in errors {
        result.add_error(error);
    }
    result
}

// ---------------------------------------------------------------------------
// ID3 metadata (`shared/lib/deezer-utils.ts` buildDeezerId3Metadata)
// ---------------------------------------------------------------------------

/// Build the ID3 payload for the download pipeline. Cover art is fetched
/// here (5 s budget); any network failure just drops the image — it never
/// blocks the cache write.
async fn build_deezer_id3_metadata(
    http: &reqwest::Client,
    track: &Value,
    track_id: &str,
    default_image: &str,
) -> TrackId3Metadata {
    let s = |key: &str| track.get(key).and_then(Value::as_str).unwrap_or("");

    let song_title = match s("SNG_TITLE") {
        "" => "Unknown Title",
        title => title,
    };
    let uploader_name = match s("ART_NAME") {
        "" => "Unknown Artist",
        name => name,
    };
    let artist = match track.get("ARTISTS").and_then(Value::as_array) {
        Some(artists) if !artists.is_empty() => artists
            .iter()
            .map(|a| a.get("ART_NAME").and_then(Value::as_str).unwrap_or(""))
            .collect::<Vec<_>>()
            .join(", "),
        _ => uploader_name.to_string(),
    };

    let thumbnail_url = match s("ALB_PICTURE") {
        "" => default_image.to_string(),
        picture => deezer_image_url(picture, "250x250"),
    };

    let mut image_jpeg = None;
    if !thumbnail_url.is_empty() {
        let fetch = async {
            let response = http.get(&thumbnail_url).send().await?;
            if response.status().is_success() {
                response.bytes().await.map(Some)
            } else {
                Ok(None)
            }
        };
        match tokio::time::timeout(THUMBNAIL_TIMEOUT, fetch).await {
            Ok(Ok(Some(bytes))) => image_jpeg = Some(bytes.to_vec()),
            Ok(Ok(None)) => {}
            Ok(Err(error)) => {
                let error: reqwest::Error = error;
                tracing::warn!(target: "DEEZER", error = %error, "Failed to download thumbnail");
            }
            Err(_) => {
                tracing::warn!(target: "DEEZER", "Failed to download thumbnail: timeout");
            }
        }
    }

    let year = track
        .get("PHYSICAL_RELEASE_DATE")
        .and_then(Value::as_str)
        .and_then(|date| date.get(..4))
        .and_then(|y| y.parse::<i32>().ok());

    let duration_ms = track
        .get("DURATION")
        .and_then(Value::as_str)
        .and_then(|seconds| seconds.parse::<u32>().ok())
        .map(|seconds| seconds * 1000);

    TrackId3Metadata {
        title: Some(song_title.to_string()),
        artist: Some(artist),
        album: Some(match s("ALB_TITLE") {
            "" => uploader_name.to_string(),
            album => album.to_string(),
        }),
        year,
        duration_ms,
        source: Some("deezer".to_string()),
        track_id: Some(track_id.to_string()),
        isrc: track.get("ISRC").and_then(Value::as_str).map(str::to_owned),
        comment: Some(thumbnail_url),
        image_jpeg,
    }
}

/// Release a held download lock, logging (never propagating) failures.
async fn release_lock(guard: DownloadLockGuard, track_id: &str) {
    if let Err(error) = guard.release().await {
        tracing::warn!(
            target: "DEEZER",
            track_id,
            error = %error,
            "Failed to release download lock"
        );
    }
}

// ---------------------------------------------------------------------------
// Casos 3-9 — tokens, formatos y archivos (impl del orquestador)
// ---------------------------------------------------------------------------

impl MusicSystem {
    /// Caso 3 — tokens de sesión/track (`getTrackTokensHandler`).
    pub async fn cancion_tokens(
        &self,
        track_id: &str,
        bw: Option<&BandwidthOp>,
    ) -> ResultEnvelope<TrackRawData> {
        let mut result = ResultEnvelope::<TrackRawData>::new();
        tracing::debug!(target: "DEEZER", track_id, "getTrackTokens controller input");

        let context = DeezerArlFailureContext {
            track_id: Some(track_id.to_string()),
            ..Default::default()
        };
        let Some(tokens) = self
            .deezer
            .fetch_session_tokens(false, Some(&context), bw)
            .await
        else {
            result.add_error(
                &ApiError::new(
                    "Invalid license token in session",
                    ErrorType::Internal,
                    ErrorContext::Api,
                )
                .with_status(401),
            );
            return result;
        };

        let token_key = deezer_track_token_key(track_id);
        let cached_token = match self.redis.get_value(&token_key).await {
            Ok(value) => value.and_then(|v| v.as_str().map(str::to_owned)),
            Err(error) => {
                tracing::error!(target: "DEEZER", error = %error, "DeezerController - getTrack");
                return internal_500();
            }
        };
        tracing::debug!(
            target: "DEEZER",
            track_id,
            cache_hit = cached_token.is_some(),
            "getTrackTokens track token cache"
        );

        let track_token = match cached_token {
            Some(token) => token,
            None => {
                let song = match self
                    .deezer
                    .get_song_data(
                        &tokens.session_id,
                        &tokens.api_token,
                        track_id,
                        Some(&context),
                        bw,
                    )
                    .await
                {
                    Ok(song) => song,
                    Err(error) => {
                        tracing::error!(target: "DEEZER", error = %error, "DeezerController - getTrack");
                        return internal_500();
                    }
                };
                if song.is_error_license_token {
                    tracing::error!(
                        target: "DEEZER",
                        track_id,
                        "DeezerController - getTrack - Invalid license token in song data"
                    );
                    result.add_error(
                        &ApiError::new(
                            "Invalid license token in song data",
                            ErrorType::Internal,
                            ErrorContext::Api,
                        )
                        .with_status(401),
                    );
                    return result;
                }

                let results = song.results.unwrap_or(Value::Null);
                let token = results
                    .get("TRACK_TOKEN")
                    .and_then(Value::as_str)
                    .unwrap_or("")
                    .to_string();
                let track_exp = results.get("TRACK_TOKEN_EXPIRE").and_then(Value::as_i64);
                let ttl = token_related_ttl(track_exp);
                if let Err(error) = self
                    .redis
                    .set_value(&token_key, &Value::String(token.clone()), Some(ttl))
                    .await
                {
                    tracing::error!(target: "DEEZER", error = %error, "DeezerController - getTrack");
                    return internal_500();
                }
                token
            }
        };

        let data = TrackRawData {
            track_id: track_id.to_string(),
            track_format: String::new(),
            session_id: tokens.session_id,
            api_token: tokens.api_token,
            license_token: tokens.license_token,
            track_token,
            track_url: String::new(),
        };
        tracing::debug!(
            target: "DEEZER",
            track_id,
            has_track_token = !data.track_token.is_empty(),
            "getTrackTokens controller response"
        );
        result.add_data(data);
        result
    }

    /// Caso 4 — formatos disponibles (probe en vivo, nunca cacheado).
    pub async fn cancion_formatos(
        &self,
        track_id: &str,
        bw: Option<&BandwidthOp>,
    ) -> ResultEnvelope<AvailableFormatsData> {
        let mut result = ResultEnvelope::<AvailableFormatsData>::new();

        if !is_numeric_track_id(track_id) {
            result.add_error(&validation_error("Valid numeric Track ID is required"));
            return result;
        }

        let deezer_formats = combined_deezer_formats();

        let granted = match self
            .deezer
            .get_available_formats(track_id, &deezer_formats, bw)
            .await
        {
            Ok(granted) => granted,
            Err(errors) => {
                for error in &errors {
                    result.add_error(error);
                }
                return result;
            }
        };

        // Priority-ordered, deduped canonical tokens.
        let formats = granted_formats_to_tokens(&granted);

        if formats.is_empty() {
            result.add_error(
                &ApiError::new(
                    "No available track format",
                    ErrorType::Service,
                    ErrorContext::Api,
                )
                .with_status(404),
            );
            return result;
        }

        result.add_data(AvailableFormatsData { formats });
        result
    }

    /// Caso 5 — archivo con formato explícito (`getTrackFileHandler`).
    pub async fn cancion_archivo(
        &self,
        track_id: &str,
        raw_format: &str,
        bw: Option<&BandwidthOp>,
    ) -> AudioServe {
        let spec = resolve_deezer_format(raw_format);
        tracing::debug!(
            target: "DEEZER",
            track_id,
            raw_format,
            track_format = spec.map(|s| s.extension),
            "getTrackFile controller input"
        );
        if !is_numeric_track_id(track_id) {
            return AudioServe::Fail(fail_with(&[validation_error(
                "Valid numeric Track ID is required",
            )]));
        }
        let Some(spec) = spec else {
            return AudioServe::Fail(fail_with(&[validation_error("Invalid track format")]));
        };

        self.serve_track_file(track_id.to_string(), spec, bw).await
    }

    /// Caso 6 — archivo con formato omitido: mejor disponible (FLAC → MP3 →
    /// AAC) por `FILESIZE_*`, con retry sin FLAC ante 403 `format_rights`.
    pub async fn cancion_archivo_default(
        &self,
        track_id: &str,
        bw: Option<&BandwidthOp>,
    ) -> AudioServe {
        tracing::debug!(target: "DEEZER", track_id, "getTrackFileDefault controller input");
        if !is_numeric_track_id(track_id) {
            return AudioServe::Fail(fail_with(&[validation_error(
                "Valid numeric Track ID is required",
            )]));
        }

        let song_data = match self.deezer.get_track_data(track_id, bw).await {
            Ok(data) => data,
            Err(errors) => return AudioServe::Fail(fail_with(&errors)),
        };
        let Some(spec) = resolve_default_deezer_format(&song_data) else {
            return AudioServe::Fail(fail_with(&[ApiError::new(
                "No available track format",
                ErrorType::Service,
                ErrorContext::Api,
            )
            .with_status(404)]));
        };
        tracing::debug!(
            target: "DEEZER",
            track_id,
            track_format = spec.extension,
            "getTrackFileDefault resolved format"
        );

        let outcome = self.serve_track_file(track_id.to_string(), spec, bw).await;

        // 403-downgrade guard: cached FILESIZE_* promised FLAC but the current
        // ARL can't serve it (tier rotation / rights). A propagated 403 would
        // let api-music dead-stamp the track (`available_buffer=false`, 72 h)
        // even though a lower format works — and in auto mode nobody upstream
        // retries. One retry with the best non-FLAC format; explicit
        // `/file/flac` keeps its plain-403 semantics. (El controlador original
        // inspeccionaba `x-error-code` en la Response; ese header lo emite el
        // envelope, así que aquí se lee la misma señal en origen.)
        if spec.token == "flac" && is_format_rights_403(&outcome) {
            if let Some(fallback) = resolve_default_deezer_format_no_flac(&song_data) {
                tracing::warn!(
                    target: "DEEZER",
                    track_id,
                    fallback_format = fallback.extension,
                    "FLAC download forbidden (403) — retrying with fallback format"
                );
                return self.serve_track_file(track_id.to_string(), fallback, bw).await;
            }
        }
        outcome
    }

    /// Caso 7 — solo-caché con formato explícito (probe, nunca descarga).
    pub async fn cancion_archivo_solo_cache(
        &self,
        track_id: &str,
        raw_format: &str,
        bw: Option<&BandwidthOp>,
    ) -> AudioServe {
        let spec = resolve_deezer_format(raw_format);
        tracing::debug!(
            target: "DEEZER",
            track_id,
            raw_format,
            track_format = spec.map(|s| s.extension),
            "getTrackFileOnlyCache controller input"
        );
        if !is_numeric_track_id(track_id) {
            return AudioServe::Fail(fail_with(&[validation_error(
                "Valid numeric Track ID is required",
            )]));
        }
        let Some(spec) = spec else {
            return AudioServe::Fail(fail_with(&[validation_error("Invalid track format")]));
        };

        let Some(file_path) = self.disk.deezer_cache_path(track_id, spec.extension) else {
            return AudioServe::Fail(fail_with(&[validation_error("Invalid track format")]));
        };
        let stat = tokio::fs::metadata(&file_path).await.ok();
        tracing::debug!(
            target: "DEEZER",
            track_id,
            track_format = spec.extension,
            cache_hit = stat.is_some(),
            file_size = stat.as_ref().map(|meta| meta.len()),
            "getTrackFileOnlyCache fs stat result"
        );
        // TS parity: the probe marks a bandwidth cache-hit even when it misses.
        if let Some(op) = bw {
            op.set_provider(BandwidthProvider::Deezer);
            op.mark_cache(CacheMark::Hit);
        }
        let Some(stat) = stat else {
            return AudioServe::Fail(fail_with(&[ApiError::new(
                "Track file not found in cache",
                ErrorType::Unknown,
                ErrorContext::Api,
            )
            .with_status(404)]));
        };

        tracing::info!(
            target: "DEEZER",
            track_id,
            origin = "deezer",
            file_size = stat.len(),
            "track file source: fs cache (probe only)"
        );
        AudioServe::File {
            path: file_path,
            content_type: spec.content_type,
        }
    }

    /// Caso 8 — solo-caché con formato omitido: probe FLAC → MP3 → AAC,
    /// primer hit gana. Nunca descarga y nunca llama a Deezer.
    pub async fn cancion_archivo_solo_cache_default(
        &self,
        track_id: &str,
        bw: Option<&BandwidthOp>,
    ) -> AudioServe {
        tracing::debug!(
            target: "DEEZER",
            track_id,
            "getTrackFileOnlyCacheDefault controller input"
        );
        if !is_numeric_track_id(track_id) {
            return AudioServe::Fail(fail_with(&[validation_error(
                "Valid numeric Track ID is required",
            )]));
        }

        // TS parity with the explicit-format probe: mark a bandwidth cache-hit
        // even when every extension misses.
        if let Some(op) = bw {
            op.set_provider(BandwidthProvider::Deezer);
            op.mark_cache(CacheMark::Hit);
        }

        for spec in [&FLAC, &MP3, &AAC] {
            let Some(file_path) = self.disk.deezer_cache_path(track_id, spec.extension) else {
                continue;
            };
            let Ok(stat) = tokio::fs::metadata(&file_path).await else {
                continue;
            };
            tracing::info!(
                target: "DEEZER",
                track_id,
                track_format = spec.extension,
                origin = "deezer",
                file_size = stat.len(),
                "track file source: fs cache (probe only, default format)"
            );
            return AudioServe::File {
                path: file_path,
                content_type: spec.content_type,
            };
        }

        AudioServe::Fail(fail_with(&[ApiError::new(
            "Track file not found in cache",
            ErrorType::Unknown,
            ErrorContext::Api,
        )
        .with_status(404)]))
    }

    /// Shared tail of the `/file` flows once the target spec is known:
    /// fs-cache short-circuit, bounded download-lock orchestration, heartbeat,
    /// download pipeline. El frontend hace el streaming del `File` devuelto.
    async fn serve_track_file(
        &self,
        track_id: String,
        spec: &'static DeezerFormatSpec,
        bw: Option<&BandwidthOp>,
    ) -> AudioServe {
        let Some(file_path) = self.disk.deezer_cache_path(&track_id, spec.extension) else {
            // Defensive: unreachable after the numeric/format validation above.
            return AudioServe::Fail(fail_with(&[validation_error("Invalid track format")]));
        };
        if let Err(error) = validate_directory(&self.disk.deezer).await {
            tracing::error!(target: "DEEZER", error = %error, "DeezerController - getTrackFile");
            return AudioServe::Fail(internal_500());
        }

        // Bounded lock acquisition (TS while-loop, 3 attempts, 60 s waits).
        let mut attempts = 0u32;
        let guard = loop {
            match DownloadLock::try_acquire(self.redis.conn(), &track_id, Some(spec.token)).await {
                Ok(Some(guard)) => {
                    if validate_file(&file_path).await {
                        if let Ok(meta) = tokio::fs::metadata(&file_path).await {
                            tracing::info!(
                                target: "DEEZER",
                                track_id,
                                origin = "deezer",
                                file_size = meta.len(),
                                "track file source: fs cache (lock owner)"
                            );
                        }
                        if let Some(op) = bw {
                            op.set_provider(BandwidthProvider::Deezer);
                            op.mark_cache(CacheMark::Hit);
                        }
                        release_lock(guard, &track_id).await;
                        return AudioServe::File {
                            path: file_path,
                            content_type: spec.content_type,
                        };
                    }
                    break guard;
                }
                Ok(None) => {
                    attempts += 1;
                    if attempts > MAX_LOCK_ATTEMPTS {
                        tracing::warn!(
                            target: "DEEZER",
                            track_id,
                            attempts = MAX_LOCK_ATTEMPTS,
                            "Download lock contention — giving up after max attempts"
                        );
                        return AudioServe::Fail(fail_with(&[ApiError::new(
                            "Download lock contention; another worker is holding the lock",
                            ErrorType::Internal,
                            ErrorContext::Api,
                        )
                        .with_status(503)]));
                    }

                    let released = match DownloadLock::wait_for(
                        self.redis.conn(),
                        &track_id,
                        LOCK_WAIT_MS,
                        Some(spec.token),
                    )
                    .await
                    {
                        Ok(released) => released,
                        Err(error) => {
                            tracing::error!(
                                target: "DEEZER",
                                error = %error,
                                "DeezerController - getTrackFile"
                            );
                            return AudioServe::Fail(internal_500());
                        }
                    };
                    if validate_file(&file_path).await {
                        if let Ok(meta) = tokio::fs::metadata(&file_path).await {
                            tracing::info!(
                                target: "DEEZER",
                                track_id,
                                origin = "deezer",
                                file_size = meta.len(),
                                "track file source: fs cache (peer downloaded)"
                            );
                        }
                        if let Some(op) = bw {
                            op.set_provider(BandwidthProvider::Deezer);
                            op.mark_cache(CacheMark::Hit);
                        }
                        return AudioServe::File {
                            path: file_path,
                            content_type: spec.content_type,
                        };
                    }
                    if !released {
                        tracing::warn!(
                            target: "DEEZER",
                            track_id,
                            attempt = attempts,
                            "Download lock wait timed out"
                        );
                    }
                }
                Err(error) => {
                    tracing::error!(target: "DEEZER", error = %error, "DeezerController - getTrackFile");
                    return AudioServe::Fail(internal_500());
                }
            }
        };

        // Heartbeat + download + cleanup run in a DETACHED task: if the client
        // aborts mid-download, hyper drops the caller's future, but the spawned
        // task keeps going — it finishes the download (populating the fs cache
        // so the retry is a cheap hit), aborts the extender and releases the
        // lock. Without the spawn, dropping the future here leaked the extender
        // loop, which kept renewing the DownloadLock forever and permanently
        // bricked the track. The task itself is bounded by the download's own
        // timeouts (60 s overall, 10 s per chunk), so it cannot outlive them.
        let task = tokio::spawn({
            let system = self.clone();
            let track_id = track_id.clone();
            let bw = bw.cloned();
            async move {
                // Heartbeat: extend OUR lock every 15 s while the download runs. A token
                // mismatch means a peer took over (e.g. our TTL lapsed during a Redis
                // outage) — the script refuses and we log, exactly like the TS extender.
                let guard = Arc::new(guard);
                let extender = {
                    let guard = Arc::clone(&guard);
                    let track_id = track_id.clone();
                    tokio::spawn(async move {
                        let mut tick = tokio::time::interval(LOCK_EXTEND_INTERVAL);
                        tick.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Delay);
                        tick.tick().await; // interval fires immediately; setInterval does not
                        loop {
                            tick.tick().await;
                            match guard.extend().await {
                                Ok(true) => {}
                                Ok(false) => tracing::warn!(
                                    target: "DEEZER",
                                    track_id,
                                    "Lock extend refused (token mismatch — peer took over?)"
                                ),
                                Err(error) => tracing::warn!(
                                    target: "DEEZER",
                                    track_id,
                                    err = %error,
                                    "Failed to extend download lock"
                                ),
                            }
                        }
                    })
                };

                tracing::info!(
                    target: "DEEZER",
                    track_id,
                    origin = "deezer",
                    "track file source: DEEZER API (downloading)"
                );

                let outcome = system
                    .download_and_serve(&track_id, spec, &file_path, bw.as_ref())
                    .await;

                // TS `finally`: clearInterval + releaseDownloadLock on every exit path.
                extender.abort();
                let _ = extender.await;
                if let Some(guard) = Arc::into_inner(guard) {
                    release_lock(guard, &track_id).await;
                }
                outcome
            }
        });
        match task.await {
            Ok(outcome) => outcome,
            Err(join_error) => {
                tracing::error!(
                    target: "DEEZER",
                    track_id,
                    error = %join_error,
                    "DeezerController - getTrackFile (download task failed)"
                );
                AudioServe::Fail(internal_500())
            }
        }
    }

    /// Cold path of the `/file` flows: track data → download URL → Blowfish
    /// pipeline → mp3val gate → manifest + counter. Split out so the caller
    /// can run the lock cleanup around every exit.
    async fn download_and_serve(
        &self,
        track_id: &str,
        spec: &'static DeezerFormatSpec,
        file_path: &FsPath,
        bw: Option<&BandwidthOp>,
    ) -> AudioServe {
        let song_data = match self.deezer.get_track_data(track_id, bw).await {
            Ok(data) => data,
            Err(errors) => return AudioServe::Fail(fail_with(&errors)),
        };

        let track_url = match self
            .deezer
            .get_track_download_url(track_id, spec.deezer_formats, spec.token, bw)
            .await
        {
            Ok(url) => url,
            Err(errors) => return AudioServe::Fail(fail_with(&errors)),
        };

        let track_key = calculate_key(track_id, &self.config.deezer.decryption_key);
        let metadata = build_deezer_id3_metadata(
            &self.http,
            &song_data,
            track_id,
            &self.config.default_image,
        )
        .await;

        let stats = match download_deezer_track(DownloadParams {
            client: self.http.clone(),
            url: track_url,
            track_key,
            final_path: file_path.to_path_buf(),
            metadata,
            container: Some(spec.container.to_string()),
            overall_timeout_ms: Some(DOWNLOAD_OVERALL_TIMEOUT_MS),
            chunk_timeout_ms: Some(DOWNLOAD_CHUNK_TIMEOUT_MS),
        })
        .await
        {
            Ok(stats) => stats,
            Err(error) => {
                tracing::error!(target: "DEEZER", error = %error, "DeezerController - getTrackFile");
                // Propagate the exact CDN status (403 = ARL no cubre/geo-block,
                // 404 = track removed) so api-music surfaces it to Lavalink.
                let upstream = match &error {
                    DownloadError::HttpStatus(status) => *status,
                    _ => 500,
                };
                let api_error = if upstream == 500 {
                    internal_error()
                } else {
                    ApiError::new(
                        format!("Deezer upstream returned HTTP {upstream}"),
                        ErrorType::Service,
                        ErrorContext::Api,
                    )
                    .with_status(upstream)
                };
                return AudioServe::Fail(fail_with(&[api_error]));
            }
        };

        if let Some(op) = bw {
            op.set_provider(BandwidthProvider::Deezer);
            op.mark_cache(CacheMark::Miss);
            op.add_upstream_received(stats.downloaded_bytes);
        }

        // Validate BEFORE registering the cache entry: a file we end up dropping
        // must never be announced in Redis as cached. Only MP3 gets the mp3val
        // rewrite; FLAC/MP4 were container-validated by the pipeline already.
        if spec.container == "mp3" {
            if let Err(fix_error) = fix_file(file_path).await {
                let meta = tokio::fs::metadata(file_path).await.ok();
                if meta.is_none_or(|m| m.len() == 0) {
                    let _ = tokio::fs::remove_file(file_path).await;
                    tracing::error!(
                        target: "DEEZER",
                        track_id,
                        err = %fix_error,
                        "mp3val left an unusable file — dropped from cache"
                    );
                    return AudioServe::Fail(fail_with(&[ApiError::new(
                        "Downloaded audio failed validation",
                        ErrorType::Internal,
                        ErrorContext::Api,
                    )
                    .with_status(502)]));
                }
                tracing::warn!(
                    target: "DEEZER",
                    track_id,
                    err = %fix_error,
                    "mp3val failed — serving unverified file"
                );
            }
        }

        let cache_key = format!("{track_id}{extension}", extension = spec.extension);
        let entry = FileManifestEntry {
            source: Some("deezer".to_string()),
            isrc: song_data
                .get("ISRC")
                .and_then(Value::as_str)
                .map(str::to_owned),
            track_id: Some(track_id.to_string()),
            origin_url: None,
            size: Some(stats.file_size),
            cached_at: Some(chrono::Utc::now().timestamp_millis()),
        };
        if let Err(error) = manifest::set_entry(&self.redis, &cache_key, &entry).await {
            tracing::error!(target: "DEEZER", error = %error, "DeezerController - getTrackFile");
            return AudioServe::Fail(internal_500());
        }

        tracing::info!(
            target: "DEEZER",
            track_id,
            origin = "deezer",
            file_size = stats.file_size,
            decrypt_ms = stats.decrypt_duration_ms,
            "track file source: DEEZER API (Rust pipeline)"
        );
        // Fire-and-forget: the handle is a spawned task, deliberately detached.
        drop(
            self.api_db
                .fire_and_forget_track_counter(TrackCounterSource::Deezer),
        );
        AudioServe::File {
            path: file_path.to_path_buf(),
            content_type: spec.content_type,
        }
    }
}

/// ¿Es el outcome un 403 etiquetado `format_rights`? Señal del retry de
/// downgrade — misma condición que el `x-error-code` que emite el envelope.
fn is_format_rights_403(outcome: &AudioServe) -> bool {
    match outcome {
        AudioServe::Fail(envelope) => {
            envelope.derived_status() == 403
                && envelope
                    .errors
                    .iter()
                    .find(|error| !error.code.is_empty())
                    .is_some_and(|error| error.code == "format_rights")
        }
        AudioServe::File { .. } => false,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn format_aliases_resolve_to_canonical_specs() {
        for alias in ["mp3", "mp3_320", "MP3_256", ".mp3", "  Mp3_64 "] {
            let spec = resolve_deezer_format(alias).expect(alias);
            assert_eq!(spec.token, "mp3", "{alias}");
        }
        assert_eq!(resolve_deezer_format(".FLAC").unwrap().token, "flac");
        for alias in ["aac", "aac_64", "m4a", "mp4"] {
            assert_eq!(
                resolve_deezer_format(alias).unwrap().token,
                "aac",
                "{alias}"
            );
        }
        for bad in ["wav", "ogg", "flacc", ""] {
            assert!(resolve_deezer_format(bad).is_none(), "{bad}");
        }
    }

    #[test]
    fn aac_spec_serves_m4a_mp4() {
        let spec = resolve_deezer_format("aac").unwrap();
        assert_eq!(spec.extension, ".m4a");
        assert_eq!(spec.content_type, "audio/mp4");
        assert_eq!(spec.container, "mp4");
        assert_eq!(spec.deezer_formats, &["AAC_64"]);
    }

    #[test]
    fn mp3_priority_list_downgrades_through_bitrates() {
        let spec = resolve_deezer_format("mp3").unwrap();
        assert_eq!(
            spec.deezer_formats,
            &["MP3_320", "MP3_256", "MP3_128", "MP3_64"]
        );
    }

    #[test]
    fn numeric_track_id_guard() {
        assert!(is_numeric_track_id("3135556"));
        assert!(!is_numeric_track_id(""));
        assert!(!is_numeric_track_id("31a556"));
        assert!(!is_numeric_track_id("-1"));
    }

    #[test]
    fn no_flac_fallback_skips_flac_and_keeps_priority() {
        // The `[1..]` slice in `resolve_default_deezer_format_no_flac` relies
        // on FLAC being the FIRST priority entry — guard the invariant.
        assert_eq!(DEFAULT_FORMAT_PRIORITY[0].1.token, "flac");

        // FLAC promised but forbidden -> best MP3 wins on the retry path.
        let full = serde_json::json!({
            "FILESIZE_FLAC": "12345",
            "FILESIZE_MP3_320": "999",
            "FILESIZE_AAC_64": "111",
        });
        assert_eq!(
            resolve_default_deezer_format_no_flac(&full).unwrap().token,
            "mp3"
        );

        // FLAC-only track -> no fallback (retry must not loop).
        let flac_only = serde_json::json!({ "FILESIZE_FLAC": "12345" });
        assert!(resolve_default_deezer_format_no_flac(&flac_only).is_none());

        // AAC-only -> fallback still finds it.
        let aac_only = serde_json::json!({ "FILESIZE_AAC_64": 111 });
        assert_eq!(
            resolve_default_deezer_format_no_flac(&aac_only)
                .unwrap()
                .token,
            "aac"
        );
    }

    #[test]
    fn default_format_prefers_highest_available() {
        let full = serde_json::json!({
            "FILESIZE_FLAC": "12345",
            "FILESIZE_MP3_320": "999",
            "FILESIZE_AAC_64": "111",
        });
        assert_eq!(resolve_default_deezer_format(&full).unwrap().token, "flac");

        // FLAC unavailable ("0") -> best MP3 bitrate wins.
        let mp3_only = serde_json::json!({
            "FILESIZE_FLAC": "0",
            "FILESIZE_MP3_320": "0",
            "FILESIZE_MP3_128": "555",
            "FILESIZE_AAC_64": "111",
        });
        assert_eq!(
            resolve_default_deezer_format(&mp3_only).unwrap().token,
            "mp3"
        );

        // Numeric (non-string) filesizes are accepted too.
        let aac_only = serde_json::json!({ "FILESIZE_AAC_64": 111 });
        assert_eq!(
            resolve_default_deezer_format(&aac_only).unwrap().token,
            "aac"
        );

        // Nothing available (zeros / missing / garbage) -> None.
        let none = serde_json::json!({ "FILESIZE_FLAC": "0", "FILESIZE_MP3_320": null });
        assert!(resolve_default_deezer_format(&none).is_none());
        assert!(resolve_default_deezer_format(&Value::Null).is_none());
    }

    #[test]
    fn combined_deezer_formats_lists_every_priority_name() {
        assert_eq!(
            combined_deezer_formats(),
            vec!["FLAC", "MP3_320", "MP3_256", "MP3_128", "MP3_64", "AAC_64"]
        );
    }

    #[test]
    fn granted_tokens_dedupe_and_keep_priority() {
        // Multiple MP3 bitrates + AAC collapse to one `mp3`, priority order.
        let granted = vec![
            "MP3_128".to_string(),
            "AAC_64".to_string(),
            "MP3_320".to_string(),
        ];
        assert_eq!(granted_formats_to_tokens(&granted), vec!["mp3", "aac"]);

        // FLAC leads; matching is case-insensitive.
        let granted = vec!["flac".to_string(), "mp3_320".to_string()];
        assert_eq!(granted_formats_to_tokens(&granted), vec!["flac", "mp3"]);

        // Nothing granted / unknown names -> empty (handler maps to 404).
        assert!(granted_formats_to_tokens(&[]).is_empty());
        assert!(granted_formats_to_tokens(&["OPUS".to_string()]).is_empty());
    }

    #[test]
    fn format_rights_403_detection_reads_envelope_signal() {
        let mut envelope = ResultEnvelope::<()>::new();
        envelope.add_error(
            &ApiError::new("denied", ErrorType::Service, ErrorContext::Api)
                .with_status(403)
                .with_code("format_rights"),
        );
        assert!(is_format_rights_403(&AudioServe::Fail(envelope)));

        let mut plain_403 = ResultEnvelope::<()>::new();
        plain_403.add_error(
            &ApiError::new("denied", ErrorType::Service, ErrorContext::Api).with_status(403),
        );
        assert!(!is_format_rights_403(&AudioServe::Fail(plain_403)));

        let mut wrong_status = ResultEnvelope::<()>::new();
        wrong_status.add_error(
            &ApiError::new("denied", ErrorType::Service, ErrorContext::Api)
                .with_status(500)
                .with_code("format_rights"),
        );
        assert!(!is_format_rights_403(&AudioServe::Fail(wrong_status)));
    }
}

//! Núcleo del sistema: `MusicSystem`, un ORQUESTADOR.
//!
//! `MusicSystem` no implementa lógica de ningún proveedor ni de ningún
//! protocolo: recibe peticiones (`MusicQuery` o métodos tipados), decide qué
//! provider(s) atienden, aplica las políticas transversales (caché Redis,
//! locks de descarga, disco, telemetría de bandwidth, contador de tracks) y
//! compone el resultado. Los providers ejecutan; los frontends traducen.
//!
//! Regla de frontera: este módulo NUNCA importa tipos de frontend (`axum`,
//! status codes, headers). Un frontend nuevo (gRPC/WS/cola) se añade como
//! módulo hermano de `src/http/` hablando sólo `MusicQuery`/`MusicOutcome`.

pub mod deezer_files;
pub mod query;
pub mod result;

use std::sync::Arc;

use serde_json::Value;

use crate::audio::disk::DiskPaths;
use crate::cache::MusicNodoRedis;
use crate::clients::ApiDbClient;
use crate::config::Config;
use crate::providers::chipbot::ChipbotService;
use crate::providers::deezer::{DeezerResult, DeezerService, DeezerTrackInfo};
use crate::providers::isrc::{IsrcError, IsrcService};
use crate::providers::radio::{RadioSearchHit, RadioService, RadioStation};
use crate::providers::spotify::{
    SpotifyError, SpotifyPlaylistSnapshot, SpotifyPlaylistWithTracks, SpotifyService, SpotifyTrack,
};
use crate::telemetry::{BandwidthOp, BandwidthRuntime};

pub use query::{MusicQuery, Necesito, Pedir, Tipo};
pub use result::{AudioServe, MusicOutcome};

/// Piezas con las que se ensambla el sistema (construidas en `app::run`).
/// Struct en vez de 11 argumentos posicionales: los campos se nombran.
pub struct MusicSystemParts {
    pub config: Arc<Config>,
    pub http: reqwest::Client,
    pub redis: MusicNodoRedis,
    pub api_db: ApiDbClient,
    pub bandwidth: BandwidthRuntime,
    pub disk: DiskPaths,
    pub deezer: DeezerService,
    pub spotify: SpotifyService,
    pub radio: RadioService,
    pub chipbot: ChipbotService,
    pub isrc: Arc<IsrcService>,
}

/// El orquestador. Clonable barato (todo Arc/pool por dentro).
#[derive(Clone)]
pub struct MusicSystem {
    config: Arc<Config>,
    http: reqwest::Client,
    redis: MusicNodoRedis,
    api_db: ApiDbClient,
    bandwidth: BandwidthRuntime,
    disk: DiskPaths,
    deezer: DeezerService,
    spotify: SpotifyService,
    radio: RadioService,
    chipbot: ChipbotService,
    isrc: Arc<IsrcService>,
}

impl MusicSystem {
    pub fn new(parts: MusicSystemParts) -> Self {
        Self {
            config: parts.config,
            http: parts.http,
            redis: parts.redis,
            api_db: parts.api_db,
            bandwidth: parts.bandwidth,
            disk: parts.disk,
            deezer: parts.deezer,
            spotify: parts.spotify,
            radio: parts.radio,
            chipbot: parts.chipbot,
            isrc: parts.isrc,
        }
    }

    /// Runtime de telemetría — lo necesita el middleware de contexto de
    /// bandwidth del frontend HTTP para finalizar cada operación.
    pub fn bandwidth(&self) -> &BandwidthRuntime {
        &self.bandwidth
    }

    // -----------------------------------------------------------------
    // pedir: cancion / necesito: informacion
    // -----------------------------------------------------------------

    /// Caso 1 — Deezer: información por ID.
    pub async fn cancion_info(
        &self,
        track_id: &str,
        bw: Option<&BandwidthOp>,
    ) -> DeezerResult<DeezerTrackInfo> {
        self.deezer.get_track_info(track_id, bw).await
    }

    /// Caso 2 — Deezer: información por ISRC.
    pub async fn cancion_info_por_isrc(
        &self,
        isrc: &str,
        bw: Option<&BandwidthOp>,
    ) -> DeezerResult<DeezerTrackInfo> {
        self.deezer.get_track_by_isrc(isrc, bw).await
    }

    /// Caso 10 — Spotify: información de track.
    pub async fn spotify_cancion_info(
        &self,
        track_id: &str,
        bw: Option<&BandwidthOp>,
    ) -> Result<Option<SpotifyTrack>, SpotifyError> {
        self.spotify.get_track(track_id, bw).await
    }

    // -----------------------------------------------------------------
    // pedir: autocompletado / busqueda
    // -----------------------------------------------------------------

    /// Caso 12 — Deezer: autocompletado de canciones.
    pub async fn autocompletar(
        &self,
        q: &str,
        limit: Option<u32>,
        bw: Option<&BandwidthOp>,
    ) -> Value {
        self.deezer.get_autocomplete(q, limit, bw).await
    }

    /// Caso 13 — Deezer: búsqueda de canciones.
    pub async fn buscar_canciones(
        &self,
        q: &str,
        limit: Option<u32>,
        bw: Option<&BandwidthOp>,
    ) -> Value {
        self.deezer.get_search_route(q, limit, bw).await
    }

    /// Caso 14 — Radio: búsqueda de canales.
    pub async fn buscar_canales(&self, q: &str, bw: Option<&BandwidthOp>) -> Vec<RadioSearchHit> {
        self.radio.search(q, bw).await
    }

    // -----------------------------------------------------------------
    // pedir: canal / playlist
    // -----------------------------------------------------------------

    /// Caso 15 — Radio: información de canal.
    pub async fn canal_info(
        &self,
        channel_id: &str,
        bw: Option<&BandwidthOp>,
    ) -> Option<RadioStation> {
        self.radio.get_channel(channel_id, bw).await
    }

    /// Caso 16 — Spotify: información de playlist (paginada).
    pub async fn playlist_info(
        &self,
        playlist_id: &str,
        limit: Option<u32>,
        offset: Option<u32>,
        bw: Option<&BandwidthOp>,
    ) -> Result<Option<SpotifyPlaylistWithTracks>, SpotifyError> {
        self.spotify.get_playlist(playlist_id, limit, offset, bw).await
    }

    /// Caso 17 — Spotify: snapshot de playlist.
    pub async fn playlist_snapshot(
        &self,
        playlist_id: &str,
        bw: Option<&BandwidthOp>,
    ) -> Result<Option<SpotifyPlaylistSnapshot>, SpotifyError> {
        self.spotify.get_playlist_snapshot(playlist_id, bw).await
    }

    // -----------------------------------------------------------------
    // pedir: isrc
    // -----------------------------------------------------------------

    /// Casos 11 y 18 — ISRC de un track (carrera de proveedores dedicada;
    /// la ruta de Spotify usa el mismo servicio).
    pub async fn resolver_isrc(
        &self,
        track_id: &str,
        bw: Option<&BandwidthOp>,
    ) -> Result<Option<String>, IsrcError> {
        self.isrc.get_isrc(track_id, bw).await
    }

    // -----------------------------------------------------------------
    // pedir: salud
    // -----------------------------------------------------------------

    /// Casos 20-23 — salud por tipo. `Sistema` es la vivacidad del propio
    /// proceso (siempre `true` si responde). Radio es hoy un stub que
    /// devuelve `true` sin sondear (paridad TS) — el gap 6 del catálogo lo
    /// cablea al probe real en la Fase 3 del refactor.
    pub async fn salud(&self, tipo: Tipo, bw: Option<&BandwidthOp>) -> bool {
        match tipo {
            Tipo::Deezer => self.deezer.health(bw).await,
            Tipo::Spotify => self.spotify.health(bw).await,
            Tipo::Radio => true,
            Tipo::Chipbot => self.chipbot.health(bw).await.ok,
            Tipo::IsrcService => self.isrc.health(bw).await,
            Tipo::Sistema => true,
        }
    }
}

//! Shared application state.
//!
//! Assembled once in `run()` after `Config::load` succeeds and every
//! backing client connects. Handlers receive it via `axum::extract::State`;
//! all fields are cheap to clone (Arc-backed or pooled clients).
//!
//! Provider services are constructed from these primitives in `run()`.

use std::sync::Arc;

use crate::audio::disk::DiskPaths;
use crate::cache::MusicNodoRedis;
use crate::clients::ApiDbClient;
use crate::config::Config;
use crate::providers::chipbot::ChipbotService;
use crate::providers::deezer::DeezerService;
use crate::providers::isrc::IsrcService;
use crate::providers::radio::RadioService;
use crate::providers::spotify::SpotifyService;
use crate::system::MusicSystem;
use crate::telemetry::BandwidthRuntime;

#[derive(Clone)]
pub struct AppState {
    pub config: Arc<Config>,
    /// Núcleo orquestador (providers + políticas transversales). Los
    /// handlers deben ir SIEMPRE a través de él; los campos de provider
    /// que siguen debajo son transitorios hasta completar la Fase 2 del
    /// refactor (ver docs/PLAN_REFACTOR.md).
    pub system: MusicSystem,
    /// Shared pooled HTTP client (upstream calls: Deezer, Spotify, radio,
    /// chipbot, Infisical). One client per process, HTTP/2 reuse.
    pub http: reqwest::Client,
    /// Redis DB 7 cache handle (codec-compatible with the TS client).
    pub redis: MusicNodoRedis,
    /// Typed api-db client (ARLs, track counter, track errors).
    pub api_db: ApiDbClient,
    /// Bandwidth telemetry runtime (store + background flush task).
    pub bandwidth: BandwidthRuntime,
    /// Disk cache roots under `/mnt/disk-songs`.
    pub disk: DiskPaths,
    /// Deezer provider (sessions, search, downloads) + its `ArlManager`.
    pub deezer: DeezerService,
    /// Spotify partner-API provider.
    pub spotify: SpotifyService,
    /// Radio Garden provider.
    pub radio: RadioService,
    /// Chipbot fallback provider.
    pub chipbot: ChipbotService,
    /// ISRC lookup provider (tools4music/groover/findmy race). Also the
    /// `IsrcResolver` implementation injected into `spotify`.
    pub isrc: Arc<IsrcService>,
}

