use std::io;
use std::path::{Component, Path, PathBuf};
use std::time::{Duration, SystemTime};

/// Shared on-disk roots used by the Deezer and Chipbot caches.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DiskPaths {
    pub root: PathBuf,
    pub deezer: PathBuf,
    pub chipbot: PathBuf,
}

impl DiskPaths {
    pub fn production() -> Self {
        Self::for_root(PathBuf::from("/mnt/disk-songs"))
    }

    pub fn for_root(root: PathBuf) -> Self {
        Self {
            deezer: root.join("tmp-deezer"),
            chipbot: root.join("tmp-chipbot"),
            root,
        }
    }

    /// Resolve a cache-controller file id without allowing lexical traversal
    /// or existing symlink components to escape the cache root.
    pub fn safe_resolve(&self, source: &str, file_id: &str) -> Option<PathBuf> {
        let base = match source {
            "deezer" => &self.deezer,
            "chipbot" => &self.root,
            _ => return None,
        };
        safe_join(base, file_id)
    }

    pub fn deezer_cache_path(&self, track_id: &str, extension: &str) -> Option<PathBuf> {
        if !is_track_id(track_id) || !is_deezer_extension(extension) {
            return None;
        }
        safe_join(&self.deezer, &format!("{track_id}{extension}"))
    }

    pub fn chipbot_cache_path(&self, isrc: &str, extension: &str) -> Option<PathBuf> {
        let isrc = normalize_isrc(isrc)?;
        if !is_audio_extension(extension) {
            return None;
        }
        safe_join(&self.chipbot, &format!("{isrc}{extension}"))
    }
}

pub fn deezer_cache_path(paths: &DiskPaths, track_id: &str, extension: &str) -> Option<PathBuf> {
    paths.deezer_cache_path(track_id, extension)
}

pub fn chipbot_cache_path(paths: &DiskPaths, isrc: &str, extension: &str) -> Option<PathBuf> {
    paths.chipbot_cache_path(isrc, extension)
}

pub const STALE_TMP_MAX_AGE: Duration = Duration::from_secs(10 * 60);
pub const AUDIO_EXTENSIONS: [&str; 6] = [".mp3", ".webm", ".flac", ".ogg", ".m4a", ".wav"];

pub fn is_track_id(value: &str) -> bool {
    !value.is_empty() && value.bytes().all(|b| b.is_ascii_digit())

