            has_audio = track
                .as_ref()
                .and_then(|track| track.audio.as_ref())
                .is_some_and(|audio| !audio.url.is_empty()),
            "getTrackFileByIsrc chipbot lookup result"
        );
        if let Some(track) = track {
            if let Some(file_path) = self.cache_chipbot_track(&track, &isrc, bw).await? {
                tracing::info!(
                    target: "CHIPBOT",
                    isrc,
                    origin = "chipbot",
                    "audio source: CHIPBOT API (downloaded + cached)"
                );
                if let Some(op) = bw {
                    op.set_provider(BandwidthProvider::Chipbot);
                    op.mark_cache(CacheMark::Miss);
                }
                // Fire-and-forget: the handle is a spawned task, deliberately detached.
                drop(
                    self.api_db
                        .fire_and_forget_track_counter(TrackCounterSource::Chipbot),
                );
                let extension = file_path
                    .extension()
                    .and_then(|extension| extension.to_str())
                    .map(|extension| format!(".{extension}"))
                    .unwrap_or_else(|| ".mp3".to_string());
                return Ok(AudioServe::File {
                    path: file_path,
                    content_type: audio_content_type(&extension),
                });
            }
        }

        Ok(not_found(format!(
            "Track file not found on Chipbot [isrc: {isrc}]"
        )))
    }

    /// Caso 9 — Chipbot: archivo solo-caché
    /// (`getTrackFileOnlyCacheByIsrcHandler`, nunca llama a Chipbot upstream).
    pub async fn cancion_archivo_chipbot_solo_cache(
        &self,
        raw_isrc: &str,
        raw_format: &str,
        bw: Option<&BandwidthOp>,
    ) -> Result<AudioServe, String> {
        let FileRequestValidation {
            isrc,
            requested_format: _,
            errors,
        } = validate_file_request(raw_isrc, raw_format);
        tracing::debug!(
            target: "CHIPBOT",
            isrc = ?isrc,
            raw_isrc,
            raw_format,
            "getTrackFileOnlyCacheByIsrc controller input"
        );
        if errors.has_errors {
            return Ok(AudioServe::Fail(errors));
        }
        let isrc = isrc.expect("validated ISRC");

        if let Some(outcome) = self.send_cached_chipbot_track(&isrc, bw).await {
            return Ok(outcome);
        }

        Ok(not_found(format!(
            "Track file not found in Chipbot cache [isrc: {isrc}]"
        )))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn validation_normalizes_isrc_and_accepts_all_ts_formats() {
        for format in ["mp3", ".webm", "flac", ".ogg", "m4a", ".wav"] {
            let validation = validate_file_request(" usrc17607839 ", format);
            assert!(!validation.errors.has_errors, "{format}");
            assert_eq!(validation.isrc.as_deref(), Some("USRC17607839"));
            assert!(is_audio_extension(&validation.requested_format));
        }
    }

    #[test]
    fn validation_accumulates_isrc_and_format_errors() {
        let validation = validate_file_request("not-an-isrc", "AAC");
        assert!(validation.errors.has_errors);
        assert_eq!(validation.errors.status_code, 400);
        assert_eq!(validation.errors.errors.len(), 2);
        assert_eq!(
            validation.errors.errors[0].message,
            "Valid ISRC is required"
        );
        assert_eq!(validation.errors.errors[1].message, "Invalid track format");
        assert!(
            validate_file_request("USRC17607839", "MP3")
                .errors
                .has_errors
        );
    }

    #[test]
    fn filename_and_manifest_mapping_are_safe_and_normalized() {
        assert_eq!(
            cache_filename(" usrc17607839 ", ".m4a").as_deref(),
            Some("USRC17607839.m4a")
        );
        assert_eq!(
            manifest_filename("usrc17607839", ".mp3").as_deref(),
            Some("tmp-chipbot/USRC17607839.mp3")
        );
        assert_eq!(cache_filename("../escape", ".mp3"), None);
        assert_eq!(cache_filename("USRC17607839", ".aac"), None);
    }

    #[test]
    fn audio_url_extension_mapping_matches_ts_fallback() {
        assert_eq!(
            audio_extension_from_url(&Url::parse("https://cdn.test/song.flac?x=1").unwrap()),
            Some(".flac")
        );
        assert_eq!(
            audio_extension_from_url(&Url::parse("https://cdn.test/song").unwrap()),
            Some(".mp3")
        );
        assert_eq!(
            audio_extension_from_url(&Url::parse("https://cdn.test/song.aac").unwrap()),
            None
        );
        assert_eq!(
            audio_extension_from_url(&Url::parse("https://cdn.test/song.MP3").unwrap()),
            None
        );
        assert!(allowed_audio_url("ftp://cdn.test/song.mp3").is_none());
        assert!(allowed_audio_url("https://cdn.test/song.mp3").is_some());
    }
}

