//! Port of `chipbot-controller.ts` (Chipbot cached-audio routes).
//!
//! Adaptador fino tras la Fase 2 del refactor: la orquestación de archivos
//! (validación de ISRC/formato, probe de fs-cache, descarga tmp+rename,
//! ID3, manifiesto y contador) vive en `crate::system::chipbot_files`; aquí
//! solo queda la traducción HTTP — Range (RFC 7233) sobre el
//! `AudioServe::File` que devuelve el núcleo, envelopes de fallo tal cual, y
//! el mapeo de `Err(String)` (fallos de E/S/red) a 500 con la causa
//! adjunta, preservando el nombre del handler en el log (paridad con el
//! `catch` del controlador TS original).

use std::path::Path as FsPath;

use axum::extract::{Extension, Path, State};
use axum::http::{header, HeaderMap};
use axum::response::{IntoResponse, Response};

use crate::audio::range::{file_response, parse_range};
use crate::error::{ApiError, ErrorContext, ErrorType, ResultEnvelope};
use crate::state::AppState;
use crate::system::AudioServe;
use crate::telemetry::BandwidthOp;

fn error_response(
    message: impl Into<String>,
    error_type: ErrorType,
    status: u16,
    cause: Option<String>,
) -> Response {
    let mut error = ApiError::new(message, error_type, ErrorContext::Api).with_status(status);
    if let Some(cause) = cause {
        error = error.with_cause(cause);
    }
    let mut result = ResultEnvelope::<()>::new();
    result.add_error(&error);
    result.into_response()
}

fn internal_error_response(cause: String) -> Response {
    error_response(
        "Internal server error",
        ErrorType::Internal,
        500,
        Some(cause),
    )
}

/// Stream the resolved file honouring `Range` (the `sendFile` surface).
async fn send_cached_file(
    headers: &HeaderMap,
    path: &FsPath,
    content_type: &'static str,
) -> Result<Response, String> {
    let metadata = tokio::fs::metadata(path)
        .await
        .map_err(|error| format!("stat cached Chipbot file: {error}"))?;
    let range = headers
        .get(header::RANGE)
        .and_then(|value| value.to_str().ok());
    Ok(file_response(
        path,
        metadata.len(),
        parse_range(range, metadata.len()),
        content_type,
        HeaderMap::new(),
    )
    .await)
}

/// Traducción `Result<AudioServe, String>` -> HTTP: archivo con Range en
/// éxito, envelope de fallo (validación/404) tal cual, cualquier otro error
/// mapeado a 500 con causa — siempre logueado con el nombre del handler que
/// originó la llamada.
async fn respond(
    headers: &HeaderMap,
    handler: &'static str,
    outcome: Result<AudioServe, String>,
) -> Response {
    let served = match outcome {
        Ok(AudioServe::File { path, content_type }) => {
            send_cached_file(headers, &path, content_type).await
        }
        Ok(AudioServe::Fail(envelope)) => return envelope.into_response(),
        Err(cause) => Err(cause),
    };
    match served {
        Ok(response) => response,
        Err(cause) => {
            tracing::error!(target: "CHIPBOT", error = cause, "ChipbotController - {handler}");
            internal_error_response(cause)
        }
    }
}

/// `getTrackFileByIsrcHandler` — downloads on cache miss.
pub async fn get_track_file_by_isrc(
    State(state): State<AppState>,
    Path((raw_isrc, raw_format)): Path<(String, String)>,
    headers: HeaderMap,
    bw: Option<Extension<BandwidthOp>>,
) -> Response {
    let bw = bw.as_ref().map(|extension| &extension.0);
    let outcome = state
        .system
        .cancion_archivo_chipbot(&raw_isrc, &raw_format, bw)
        .await;
    respond(&headers, "getTrackFileByIsrc", outcome).await
}

/// `GET /chipbot/tracks/{isrc}/file` — format omitted, defaults to mp3.
pub async fn get_track_file_by_isrc_default(
    State(state): State<AppState>,
    Path(raw_isrc): Path<String>,
    headers: HeaderMap,
    bw: Option<Extension<BandwidthOp>>,
) -> Response {
    let bw = bw.as_ref().map(|extension| &extension.0);
    let outcome = state
        .system
        .cancion_archivo_chipbot(&raw_isrc, "mp3", bw)
        .await;
    respond(&headers, "getTrackFileByIsrcDefault", outcome).await
}

/// `getTrackFileOnlyCacheByIsrcHandler` — never calls Chipbot upstream.
pub async fn get_track_file_only_cache_by_isrc(
    State(state): State<AppState>,
    Path((raw_isrc, raw_format)): Path<(String, String)>,
    headers: HeaderMap,
    bw: Option<Extension<BandwidthOp>>,
) -> Response {
    let bw = bw.as_ref().map(|extension| &extension.0);
    let outcome = state
        .system
        .cancion_archivo_chipbot_solo_cache(&raw_isrc, &raw_format, bw)
        .await;
    respond(&headers, "getTrackFileOnlyCacheByIsrc", outcome).await
}

/// `GET /chipbot/tracks/{isrc}/file/only-cache` — format omitted, defaults to mp3.
pub async fn get_track_file_only_cache_by_isrc_default(
    State(state): State<AppState>,
    Path(raw_isrc): Path<String>,
    headers: HeaderMap,
    bw: Option<Extension<BandwidthOp>>,
) -> Response {
    let bw = bw.as_ref().map(|extension| &extension.0);
    let outcome = state
        .system
        .cancion_archivo_chipbot_solo_cache(&raw_isrc, "mp3", bw)
        .await;
    respond(&headers, "getTrackFileOnlyCacheByIsrcDefault", outcome).await
}

