    {
        Ok(response) => response,
        Err(error) => {
            tracing::error!(
                target: "CHIPBOT",
                error,
                "ChipbotController - getTrackFileOnlyCacheByIsrc"
            );
            internal_error_response(error)
        }
    }
}

/// `GET /chipbot/tracks/{isrc}/file/only-cache` — format omitted, defaults to mp3.
pub async fn get_track_file_only_cache_by_isrc_default(
    State(state): State<AppState>,
    Path(raw_isrc): Path<String>,
    headers: HeaderMap,
    bw: Option<Extension<BandwidthOp>>,
) -> Response {
    let bw = bw.as_ref().map(|extension| &extension.0);
    match get_track_file_only_cache_by_isrc_inner(&state, raw_isrc, "mp3".to_string(), &headers, bw)
        .await
    {
        Ok(response) => response,
        Err(error) => {
            tracing::error!(
